inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"self-controlled\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-3\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-jita\",{\"href\":\"/en/search/synonyms/?original=jita\",\"children\":[\"$\",\"em\",null,{\"children\":\"jita\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-indriyaḥ\",{\"href\":\"/en/search/synonyms/?original=indriyaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"indriyaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"having conquered the senses\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-4\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-sarva\",{\"href\":\"/en/search/synonyms/?original=sarva\",\"children\":[\"$\",\"em\",null,{\"children\":\"sarva\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-bhūta\",{\"href\":\"/en/search/synonyms/?original=bhūta\",\"children\":[\"$\",\"em\",null,{\"children\":\"bhūta\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"to all living entities\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-5\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ātma\",{\"href\":\"/en/search/synonyms/?original=ātma\",\"children\":[\"$\",\"em\",null,{\"children\":\"ātma\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-bhūta\",{\"href\":\"/en/search/synonyms/?original=bhūta\",\"children\":[\"$\",\"em\",null,{\"children\":\"bhūta\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-4-ātmā\",{\"href\":\"/en/search/synonyms/?original=ātmā\",\"children\":[\"$\",\"em\",null,{\"children\":\"ātmā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"compassionate\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-6\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-kurvan\",{\"href\":\"/en/search/synonyms/?original=kurvan\",\"children\":[\"$\",\"em\",null,{\"children\":\"kurvan\"}]}],\" \",[\"$\",\"$L20\",\"wfwundefined-2-api\",{\"href\":\"/en/search/synonyms/?original=api\",\"children\":[\"$\",\"em\",null,{\"children\":\"api\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"although engaged in work\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-7\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-na\",{\"href\":\"/en/search/synonyms/?original=na\",\"children\":[\"$\",\"em\",null,{\"children\":\"na\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"never\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-8\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-lipyate\",{\"href\":\"/en/search/synonyms/?original=lipyate\",\"children\":[\"$\",\"em\",null,{\"children\":\"lipyate\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"is entangled\"}}],\".\"]}]]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"1597-translation,1597-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L2a\",\"child-1601\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"One who works in devotion, who is a pure soul, and who controls his mind and senses is dear to everyone, and everyone is dear to him. Though always working, such a man is never entangled.\"}}]}]}]]]}]\n32:T850,"])self.__next_f.push([1,"One who is on the path of liberation by Kṛṣṇa consciousness is very dear to every living being, and every living being is dear to him. This is due to his Kṛṣṇa consciousness. Such a person cannot think of any living being as separate from Kṛṣṇa, just as the leaves and branches of a tree are not separate from the tree. He knows very well that by pouring water on the root of the tree, the water will be distributed to all the leaves and branches, or by supplying food to the stomach, the energy is automatically distributed throughout the body. Because one who works in Kṛṣṇa consciousness is servant to all, he is very dear to everyone. And because everyone is satisfied by his work, he is pure in consciousness. Because he is pure in consciousness, his mind is completely controlled. And because his mind is controlled, his senses are also controlled. Because his mind is always fixed on Kṛṣṇa, there is no chance of his being deviated from Kṛṣṇa. Nor is there a chance that he will engage his senses in matters other than the service of the Lord. He does not like to hear anything except topics relating to Kṛṣṇa; he does not like to eat anything which is not offered to Kṛṣṇa; and he does not wish to go anywhere if Kṛṣṇa is not involved. Therefore, his senses are controlled. A man of controlled senses cannot be offensive to anyone. One may ask, “Why then was Arjuna offensive (in battle) to others? Wasn’t he in Kṛṣṇa consciousness?” Arjuna was only superficially offensive because (as has already been explained in the Second Chapter) all the assembled persons on the battlefield would continue to live individually, as the soul cannot be slain. So, spiritually, no one was killed on the Battlefield of Kurukṣetra. Only their dresses were changed by the order of Kṛṣṇa, who was personally present. Therefore Arjuna, while fighting on the Battlefield of Kurukṣetra, was not really fighting at all; he was simply carrying out the orders of Kṛṣṇa in full Kṛṣṇa consciousness. Such a person is never entangled in the reactions of work."])self.__next_f.push([1,"2f:[\"$\",\"div\",\"1597-purport,1597-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"cla